{% extends "smart_power/templates/print/base_rtl.html" %}
{% block title %}<h2>{{ _("Print Sample") }}</h2>{% endblock %}
{% block body %}
<p>{{ _("This sample shows the Smart Power letterhead, the Arabic font and the shared print helpers.") }}</p>
<p>عرض سعر محطة طلمبات بإنفرتر <span>INVT GD100</span> وألواح <span>JA Solar 625W</span> بتاريخ {{ ar_date(frappe.utils.today()) }}.</p>
<p>{{ _("Total") }}: <span class="sp-num">{{ money(125450.50) }}</span></p>
<p class="sp-words">{{ ar_words(125450.50) }}</p>
<table class="sp-table">
	<thead><tr><th>#</th><th>{{ _("Item") }}</th><th>{{ _("Qty") }}</th><th>{{ _("Amount") }}</th></tr></thead>
	<tbody>
	{%- for i in range(doc.get("sample_rows") or 8) %}
		<tr><td class="sp-num">{{ loop.index }}</td><td>لوح شمسي JA Solar 625W</td><td class="sp-num">{{ loop.index * 2 }}</td><td class="sp-amount">{{ money(loop.index * 1250) }}</td></tr>
	{%- endfor %}
	</tbody>
</table>
{{ qr(frappe.utils.get_url()) }}
{% endblock %}
{% block signatures %}{{ signature_block() }}{% endblock %}
